import{_ as i,l,o as e,c as o,v as t,p as S,x as s,d as n,i as p,S as M}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"MSS 与钳制","description":"","frontmatter":{"title":"MSS 与钳制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mss-clamping.md","filePath":"cs/mss-clamping.md","lastUpdated":1789023840000}'),d={name:"cs/mss-clamping.md"};function T(c,a,m,P,h,E){const r=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="mss-与钳制" tabindex="-1">MSS 与钳制 <a class="header-anchor" href="#mss-与钳制" aria-label="Permalink to &quot;MSS 与钳制&quot;">​</a></h1><div class="epigraph"><p>MSS 是对端愿意收的最大段；路径更小时应 PMTUD，边缘用钳制改 SYN 里的 MSS，是权宜，会把整条连接钉死在保守值。</p><footer>—— 据 RFC 9293 TCP；RFC 6691 MSS 与 IP 选项；RFC 4821 对照整理</footer></div><p><a href="/cs/pmtud">PMTUD</a> 与 <a href="/cs/jumbo-mtu">巨帧</a> 已给路径最小。<a href="/cs/window-scale-timestamps">上一课</a> 放大窗口。缺口是 <strong>MSS 选项与 MSS clamping</strong>：隧道口、PPPoE、VLAN 如何在 SYN 上减 40。本课不把 TCP 状态图画完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>段太大则分片或黑洞。主机按本机 MTU 广告 MSS（IPv4 常 MTU−40）。中间看不到数据 MTU 时，用钳制把 SYN/SYN-ACK 的 MSS 改小，强迫两端用小段，避开 ICMP。代价：即使路径能 9000，连接仍 1460；TSO 后课会在网卡再切。IPv6 钳制同样存在。GRE/VXLAN 边缘最爱用。</p><p>不要把 MSS 写成 MTU：MSS 是 TCP 载荷，MTU 是 IP 包。</p><p><span class="marginnote">RFC 9293。钳制是运营技巧，不是 TCP 状态机一步。本课不鼓励在核心乱改包。</span></p><h3 id="mss-不是-mtu" tabindex="-1">MSS 不是 MTU <a class="header-anchor" href="#mss-不是-mtu" aria-label="Permalink to &quot;MSS 不是 MTU&quot;">​</a></h3><p>钳制改 SYN，避开黑洞也钉死段大小。优先统一 MTU 或真 PMTUD。乱钳到 536 会毁掉现代网。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：PMTUD 动态 vs 钳制定静态。画：SYN MSS=9000 → 边缘改 1420 → 全程小段。与 BDP：小 MSS 使每 RTT 加一更细，但也更多头税。</p>',11)),(e(),S(M,null,{default:s(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADV%5B%22%E5%B9%BF%E5%91%8A%20MSS%22%5D%20--%3E%20PATH%5B%22%E7%9C%9F%E5%AE%9E%E8%B7%AF%E5%BE%84%20MTU%22%5D%0A%20%20PATH%20--%3E%20PMTU%5B%22PMTUD%22%5D%0A%20%20ADV%20--%3E%20CLAMP%5B%22%E8%BE%B9%E7%BC%98%E9%92%B3%E5%88%B6%20SYN%22%5D%0A%20%20CLAMP%20--%3E%20SMALL%5B%22%E8%BF%9E%E6%8E%A5%E9%92%89%E5%9C%A8%E5%B0%8F%E6%AE%B5%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>快重传按段计；MSS 变，三个 dupACK 的字节数变。RoCE 用自己的 MTU，不借 MSS。QUIC 用 PMTUD/PLPMTUD 在 UDP 上。安全：钳制可被中间人用来降效，与 ICMP 缩小同类，需信任边缘。</p><p>数据中心统一 MTU 则少钳制。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 TCP 分段卸载的全部。TCP 状态机是下一课。后课默认：MSS 来自对端与路径；钳制是边缘补丁。</p><p>把 MSS 钳到 536「为了兼容」会毁掉现代网。</p><p>上一课留下的缺口在本课收口；「MSS 与钳制」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/tcp-state-machine">TCP 状态机</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MSS 约束 TCP 段，关系是 MTU 减头。</li><li>钳制改 SYN，避开黑洞也钉死大小。</li><li>优先统一 MTU 或真 PMTUD。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9293；RFC 4821。</li></ul>',10))])}const u=i(d,[["render",T]]);export{_ as __pageData,u as default};
